CREATE TABLE IF NOT EXISTS kyc (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),status TEXT DEFAULT 'pending',rejection_reason TEXT,documents JSONB,submitted_at TIMESTAMPTZ DEFAULT NOW(),reviewed_at TIMESTAMPTZ,reviewed_by TEXT);
CREATE TABLE IF NOT EXISTS virtual_cards (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),card_number TEXT,expiry TEXT,cvv TEXT,card_type TEXT,status TEXT DEFAULT 'active',balance NUMERIC(20,8) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS card_transactions (id SERIAL PRIMARY KEY,card_id TEXT REFERENCES virtual_cards(id),user_id TEXT REFERENCES users(id),merchant TEXT,amount NUMERIC(20,8),type TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS p2p_ads (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),type TEXT,amount NUMERIC(20,8),price NUMERIC(20,8),currency TEXT,status TEXT DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS p2p_trades (id TEXT PRIMARY KEY,ad_id TEXT REFERENCES p2p_ads(id),buyer_id TEXT REFERENCES users(id),seller_id TEXT REFERENCES users(id),amount NUMERIC(20,8),status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY,sender_id TEXT REFERENCES users(id),receiver_id TEXT REFERENCES users(id),amount NUMERIC(20,8),note TEXT,status TEXT DEFAULT 'completed',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),subject TEXT,category TEXT,status TEXT DEFAULT 'open',priority TEXT DEFAULT 'normal',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ticket_messages (id SERIAL PRIMARY KEY,ticket_id TEXT REFERENCES tickets(id),sender_id TEXT,message TEXT,is_admin BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS draw_tickets (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),draw_id TEXT,quantity INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS security_events (id SERIAL PRIMARY KEY,user_id TEXT REFERENCES users(id),event_type TEXT,ip_address TEXT,device TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS login_history (id SERIAL PRIMARY KEY,user_id TEXT REFERENCES users(id),ip_address TEXT,device TEXT,location TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS referrals (id SERIAL PRIMARY KEY,referrer_id TEXT REFERENCES users(id),referred_id TEXT REFERENCES users(id),bonus NUMERIC(20,8) DEFAULT 0,status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS follows (id SERIAL PRIMARY KEY,follower_id TEXT REFERENCES users(id),following_id TEXT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(follower_id,following_id));
CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY,title TEXT,content TEXT,author_id TEXT,status TEXT DEFAULT 'published',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY,title TEXT,description TEXT,type TEXT,reward_cash NUMERIC(20,8) DEFAULT 0,reward_items TEXT,deadline TIMESTAMPTZ,max_applications INTEGER,status TEXT DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS campaign_applications (id TEXT PRIMARY KEY,campaign_id TEXT REFERENCES campaigns(id),user_id TEXT REFERENCES users(id),message TEXT,video_link TEXT,status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS promo_codes (id TEXT PRIMARY KEY,code TEXT UNIQUE,discount NUMERIC(10,4),type TEXT,max_uses INTEGER,uses INTEGER DEFAULT 0,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY,value JSONB,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS broadcasts (id TEXT PRIMARY KEY,title TEXT,content TEXT,type TEXT,sent_by TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS surveys (id TEXT PRIMARY KEY,title TEXT,questions JSONB,status TEXT DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS survey_responses (id SERIAL PRIMARY KEY,survey_id TEXT REFERENCES surveys(id),user_id TEXT REFERENCES users(id),answers JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS prediction_events (id TEXT PRIMARY KEY,title TEXT,options JSONB,status TEXT DEFAULT 'open',result TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS prediction_bets (id TEXT PRIMARY KEY,event_id TEXT REFERENCES prediction_events(id),user_id TEXT REFERENCES users(id),option TEXT,amount NUMERIC(20,8),status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS targeted_announcements (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),title TEXT,content TEXT,read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
